function f = HS77_f(x)
f = (x(1) - 1).^2 + (x(1) - x(2)).^2 + (x(3) - 1).^2 + (x(4) - 1).^4 + (x(5) - 1).^6;
end

function g = HS77_g(x)
g = zeros(5, 1);
g(1) = 4*x(1) - 2*x(2) - 2;
g(2) = -2*x(1) + 2*x(2);
g(3) = 2*x(3) - 2;
g(4) = 4*(x(4) - 1).^3;
g(5) = 6*(x(5) - 1).^5;
end

function c = HS77_c(x)
c = zeros(2, 1);
c(1) = x(1).^2.*x(4) + sin(x(4) - x(5)) - 2*sqrt(2);
c(2) = x(2) + x(3).^4.*x(4).^2 - 8 - sqrt(2);
end

function J = HS77_J(x)
J = zeros(2, 5);
J(1, 1) = 2*x(1).*x(4);
J(1, 4) = x(1).^2 + cos(x(4) - x(5));
J(1, 5) = -cos(x(4) - x(5));
J(2, 2) = 1;
J(2, 3) = 4*x(3).^3.*x(4).^2;
J(2, 4) = 2*x(3).^4.*x(4);
end
